    assert rectangles and all(rectangle.y0 > 25 for rectangle in rectangles), page.number + 1
    bounds = pymupdf.Rect(rectangles[0])
    for rectangle in rectangles[1:]:
        bounds |= rectangle
    if str(page.number + 1) in crops:
        x0, y0, x1, y1 = crops[str(page.number + 1)]
        bounds = pymupdf.Rect(bounds.x0 + bounds.width * x0, bounds.y0 + bounds.height * y0, bounds.x0 + bounds.width * x1, bounds.y0 + bounds.height * y1)
    pixmap = page.get_pixmap(matrix=pymupdf.Matrix(args.scale, args.scale), clip=bounds)
    image = Image.frombytes("RGB", (pixmap.width, pixmap.height), pixmap.samples)
    gray = image.convert("L")
    ink = ImageChops.invert(gray).point(lambda value: 255 if value > 30 else 0).getbbox()
    assert ink is not None, page.number + 1
    x0, y0, x1, y1 = ink
    return image.crop((0 if args.whole_width else max(0, x0 - 10), max(0, y0 - 10), image.width if args.whole_width else min(image.width, x1 + 10), min(image.height, y1 + 10)))


model, processor = load(str(work / "302-ocr-model"), trust_remote_code=False)
completed = set()
if args.output.exists():
    completed = {json.loads(line)["page"] for line in args.output.read_text().splitlines()}

with pymupdf.open(source) as document, args.output.open("a", encoding="utf-8", buffering=1) as stream:
    pending = [number for number in args.pages or range(2, len(document) + 1) if number not in completed]
    for offset in range(0, len(pending), args.batch):
        started = time.monotonic()
        numbers = pending[offset:offset + args.batch]
        images = [extract_question(document[number - 1]) for number in numbers]
        prompts = ["Formula Recognition:" if str(number) in crops else "OCR:" for number in numbers]
        response = batch_generate(model, processor, images=images, prompts=prompts, max_tokens=768, group_by_shape=not args.mixed_batch)
        assert len(response.texts) == len(numbers)
        for number, image, result in zip(numbers, images, response.texts):
            stream.write(json.dumps({"page": number, "size": image.size, "text": result.strip()}, ensure_ascii=False) + "\n")
        print(numbers[0], numbers[-1], round(time.monotonic() - started, 2), flush=True)
