import difflib
import json
import re

from inspect_lilin_high_math import edited_text, read_cache, work


def chinese(text):
    return re.sub(r"[^\u3400-\u9fff]", "", text)


source = read_cache("ocr")
vision = read_cache("vision")
edits = json.loads((work / "lilin-high-math-edits.json").read_text())
items = []
for number, record in vision.items():
    body, _ = edited_text(source[number], edits)
    known = chinese(body)
    for line in record["lines"]:
        text = chinese(line["text"])
        if len(text) < 8 or "微信公众号" in text:
            continue
        ratio = sum(match.size for match in difflib.SequenceMatcher(None, text, known, autojunk=False).get_matching_blocks()) / len(text)
        if ratio < 0.75:
            items.append((round(ratio, 2), number, line["text"]))
for item in sorted(items):
    print(*item)

